package org.cloudburstmc.protocol.bedrock.codec.v2193.serializer;

import io.netty.buffer.ByteBuf;
import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper;
import org.cloudburstmc.protocol.bedrock.codec.v291.serializer.ChangeDimensionSerializer_v291;
import org.cloudburstmc.protocol.bedrock.packet.ChangeDimensionPacket;

/**
 * The 2193 schema writes an unconditional, little-endian uint32 loading
 * screen ID. The v712 optional-bool wire framing is not valid for 2193.
 *
 * <p>Zero is the empty/no-associated-screen sentinel. Nonzero IDs are
 * generated by the server on each real dimension change.</p>
 */
public final class ChangeDimensionSerializer_v2193 extends ChangeDimensionSerializer_v291 {
    public static final ChangeDimensionSerializer_v2193 INSTANCE = new ChangeDimensionSerializer_v2193();

    private ChangeDimensionSerializer_v2193() {
    }

    @Override
    public void serialize(ByteBuf buffer, BedrockCodecHelper helper, ChangeDimensionPacket packet) {
        super.serialize(buffer, helper, packet);
        buffer.writeIntLE(packet.getLoadingScreenId() == null ? 0 : packet.getLoadingScreenId());
    }

    @Override
    public void deserialize(ByteBuf buffer, BedrockCodecHelper helper, ChangeDimensionPacket packet) {
        super.deserialize(buffer, helper, packet);
        int loadingScreenId = buffer.readIntLE();
        packet.setLoadingScreenId(loadingScreenId == 0 ? null : loadingScreenId);
    }
}
